def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    rich_aggressive = 0
    weak_opponents = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('budget', 0) >= 300 and opp.get('hp', 0) >= 5:
            rich_aggressive += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            weak_opponents += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    contested_units = int(supply / WATER_REQ)
    scarcity = contested_units <= 1
    ample = contested_units >= 2

    danger = hp <= 2 or no_water_days >= 2
    caution = hp <= 4 or no_water_days >= 1

    if danger:
        if highest_prev >= 100:
            bid = 96.0
        elif highest_prev >= 70:
            bid = highest_prev + 4.0
        else:
            bid = 78.0
    elif scarcity:
        if rich_aggressive >= 2:
            bid = 11.0 if hp >= 6 else 32.0
        elif highest_prev >= 90:
            bid = 14.0 if hp >= 6 else 40.0
        elif highest_prev >= 50:
            bid = 26.0 if hp >= 6 else highest_prev + 3.0
        else:
            bid = max(24.0, avg_prev + 2.0)
    elif ample:
        if highest_prev >= 90:
            bid = 8.0 if hp >= 5 else 22.0
        elif highest_prev >= 60:
            bid = 16.0 if hp >= 5 else 28.0
        else:
            bid = 21.0
    else:
        bid = 20.0

    if weak_opponents >= 2 and hp >= 5:
        bid *= 0.85

    if budget < 80:
        bid = min(bid, budget * 0.55 + 6.0)
    elif budget < 160:
        bid = min(bid, budget * 0.7)

    if day_context['day'] >= 8 and hp >= 5:
        bid *= 0.9
    if day_context['day'] >= 9 and hp <= 3:
        bid = max(bid, 72.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if 'previous_trace' in o and o['previous_trace'].get('bid') is not None]

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 40.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if supply < WATER_REQ * 1.5:
        return min(my_status['budget'], avg_opp_bid + 5.0)

    return min(my_status['budget'], max(20.0, avg_opp_bid * 0.8))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = day_context['supply']
    day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {aid: opp for aid, opp in opponents_status.items() if opp['alive']}
    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)
    # Determine opponent with highest previous bid
    highest_prev_bid = 0
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            if prev['bid'] > highest_prev_bid:
                highest_prev_bid = prev['bid']
    # Critical HP threshold
    if my_hp <= 2 or no_water_days >= 1:
        return min(my_budget, DAILY_SALARY * 0.9)
    # Early days: conserve but stay alive
    if day <= 3:
        return min(my_budget, max(DAILY_SALARY * 0.3, highest_prev_bid + 0.5))
    # Mid-late game: compete more
    # If opponent's previous bid was very high, they might overbid again
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        if my_hp > 3:
            return min(my_budget, DAILY_SALARY * 0.25)
        else:
            return min(my_budget, DAILY_SALARY * 0.75)
    # Normal: try to slightly beat the highest previous bid
    target = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.0)
    return min(my_budget, target)
